const transport = m.defineTransport({ name: "t", inbound: { parts: ["data"] } });
const c = transport.contract({ inbound: {} });
const g = m.createReceiver(c, "inbound");
export type _guardNotAny = Expect<IsAny<ReturnType<typeof g>>>;
export type _entryNotAny = Expect<IsAny<t.ContractEntry["encoding"]>>;
export type _receivedNotAny = Expect<IsAny<t.Received<typeof c, "inbound">>>;
export type _sentNotAny = Expect<IsAny<t.Sent<typeof c, "inbound">>>;
export type _outcomeNotAny = Expect<IsAny<t.StandardOutcome<number>>>;
export const _logger: t.ContractLoggerLike = { warn: (_m: string) => {}, error: (_m: string) => {} };
export const _sink: t.ContractLoggerLike = (e: t.ContractLogEvent) => void e.message;
const g2 = m.createReceiver(c, "inbound", { policy: "warn", logger: _sink });
export type _g2NotAny = Expect<IsAny<typeof g2>>;
// @ts-expect-error a logger needs warn and error
m.createReceiver(c, "inbound", { logger: { warn: () => {} } });
